span {
  width: 100px;       /* ❌ 行内元素无效 */
  margin-top: 50px;   /* ❌ 无法推开其他元素 */
  background: red;    /* ✅ 背景色有效 */
}

/* 修复方案 */
span {
  display: inline-block; /* 核心修复 */
  width: 100px;       
  margin-top: 50px;   
}

.text {
  color: red !important;
}

