const list = [1, 2];

// ✅ 成功执行：只是修改了数组内部的内容，没有改变变量的指向
list.push(3);

// ❌ 报错：试图将 list 指向一个全新的数组，违背了 const 规则
list = [1, 2, 3];

const nums = [1, 2, 3];

// ❌ 错误写法：加了花括号，却没有写 return
const result = nums.map(n => { n * 2 });
console.log(result); // [undefined, undefined, undefined]

// ✅ 修复方案 1：去掉花括号，利用隐式返回
const result1 = nums.map(n => n * 2);

// ✅ 修复方案 2：保留花括号，但手动加上 return
const result2 = nums.map(n => { return n * 2 });

let userA = { name: "张三" };

// 仅仅是复制了地址，并没有复制对象本身
let userB = userA;

// 修改 userB，实际上修改的是共享的那个对象
userB.name = "李四";

console.log(userA.name); // 输出: 李四

const val = 0;

// 0 是 Falsy 值，转换后相当于 if(false)
if (val) {
  console.log("A");
} else {
  console.log("B"); // 代码执行到这里
}

const [list, setList] = useState([1, 2]);

// ❌ 错误写法：直接修改原数组，地址未变，React 拒绝渲染
const addError = () => {
  list.push(3);
  setList(list);
};

// ✅ 正确写法：创建一个新数组，地址改变，触发渲染
const addCorrect = () => {
  setList([...list, 3]);
};

// ❌ 错误：有花括号却没有 return
<ul>
  {data.map(item => {
    <li key={item.id}>{item.name}</li>
  })}
</ul>

// ✅ 修复方案 1：改用圆括号 ()，隐式返回
<ul>
  {data.map(item => (
    <li key={item.id}>{item.name}</li>
  ))}
</ul>

// ✅ 修复方案 2：保留花括号 {}，手动 return
<ul>
  {data.map(item => {
    return <li key={item.id}>{item.name}</li>;
  })}
</ul>

const count = 0;

// ❌ 错误：会渲染出数字 0
return <div>{count && <span>收到新消息</span>}</div>;

// ✅ 修复方案 1：使用比较运算符，强行转为布尔值
return <div>{count > 0 && <span>收到新消息</span>}</div>;

// ✅ 修复方案 2：使用双非运算符 !! 强转布尔值
return <div>{!!count && <span>收到新消息</span>}</div>;

// ✅ 修复方案 3：改用三元表达式（最稳妥）
return <div>{count ? <span>收到新消息</span> : null}</div>;

// ❌ 错误：组件一渲染，当场执行，点击无效
<button onClick={handleClick()}>点击</button>

// ✅ 正确：只传引用，不加括号
<button onClick={handleClick}>点击</button>

// ✅ 正确：如果要传参数，必须套一层箭头函数
<button onClick={() => handleClick(id)}>点击</button>

