/* ❌ 性能差，每一帧都会重新计算布局（回流） */
.box-bad {
  position: relative;
  left: 0;
  transition: left 0.3s;
}
.box-bad:hover {
  left: 100px;
}

/* ✅ 性能极佳，触发 GPU 硬件加速图层合成 */
.box-good {
  transform: translateX(0);
  transition: transform 0.3s;
}
.box-good:hover {
  transform: translateX(100px);
}
